    if c < len(line40) and line40[c] != ' ':
        chars.append((c, line40[c]))

# Find the segment containing col 3051
print('Chars on line 40 around 3051:')
# cluster into segments with gap <= 10
segs = []
cur = []
for c, ch in chars:
    if not cur or c - cur[-1][0] <= 10:
        cur.append((c, ch))
    else:
        segs.append(cur)
        cur = [(c, ch)]
if cur:
    segs.append(cur)

for s in segs:
    if s[0][0] <= 3051 <= s[-1][0]:
        print(f'Segment on line 40: from {s[0][0]} to {s[-1][0]}')
        # Check where incoming line from above enters this segment
